import hashlib
import hmac

SALT = b"vault-salt"

def make_verifier(master):
    h = SALT + master.encode("utf-8")
    for _ in range(1000):
        h = hashlib.sha256(h).digest()
    return h.hex()

def unlock(master, verifier):
    return hmac.compare_digest(make_verifier(master), verifier)

master = input()
attempt = input()
v = make_verifier(master)
print("unlocked" if unlock(attempt, v) else "denied")

class Vault:
    def __init__(self):
        self.items = {}

    def add(self, site, user, pw):
        if site in self.items:
            raise ValueError("exists")
        self.items[site] = (user, pw)

    def show(self, site):
        user, pw = self.items[site]
        return user + " " + "*" * len(pw)

    def reveal(self, site):
        return self.items[site][1]

    def sites(self):
        return sorted(self.items)

v = Vault()
while True:
    parts = input().split()
    if parts[0] == "exit":
        break
    try:
        if parts[0] == "add":
            v.add(parts[1], parts[2], parts[3])
            print("saved")
        elif parts[0] == "show":
            print(v.show(parts[1]))
        elif parts[0] == "list":
            print(" ".join(v.sites()))
    except ValueError:
        print("exists")
    except KeyError:
        print("missing")

import hashlib
import hmac
import json

KEY = b"integrity-key"

def seal(items):
    data = json.dumps(items, sort_keys=True)
    tag = hmac.new(KEY, data.encode("utf-8"), "sha256").hexdigest()
    return {"data": data, "tag": tag}

def open_sealed(blob):
    expected = hmac.new(KEY, blob["data"].encode("utf-8"), "sha256").hexdigest()
    if not hmac.compare_digest(expected, blob["tag"]):
        raise ValueError("tampered")
    return json.loads(blob["data"])

blob = seal({"mail": ["sara", "pw1"], "bank": ["sara", "pw2"]})
print(sorted(open_sealed(blob)))
mode = input()
if mode == "tamper":
    blob["data"] = blob["data"].replace("pw1", "evil")
try:
    print(sorted(open_sealed(blob)))
except ValueError as e:
    print(e)
